// #1280: a slice dependency written the supported way (`slice.yaml execution.depends_on` naming the generated SPEC ID)
// must resolve in mission proof readiness and in the execution view's Q2, as the folder and `metadata.id` forms do.
// The slice files below are the scaffold's generated bytes (no `metadata.id`), plus the manifest edge and one authored
// proof line each. Existing matches win first; only an otherwise-unknown name may resolve by a SPEC identity, and only
// when exactly one active member declares it.
import { afterEach, describe, expect, it } from "vitest";
import * as fs from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import YAML from "yaml";
import { createDb } from "../src/db/connection.js";
import { migrate } from "../src/db/migrate.js";
import { ALL_MIGRATIONS } from "../src/db/all-migrations.js";
import { buildExecutionView } from "../src/domain/execution-view.js";
import { readMissionReadiness, readSliceReadiness, recordJudgment } from "../src/domain/proof/judgments.js";

const MISSION = "readiness-probe";
const GENERATED_SLICE = `schema: openrig.slice/v0alpha1
kind: slice
composition:
  mission: ../../mission.yaml
  slice_markdown:
    spec: SPEC.md
    progress: PROGRESS.md
    proof: PROOF.md
# Optional assignment, SDLC, and evidence sections are added here.
`;

const roots: string[] = [];
afterEach(() => { for (const p of roots.splice(0)) fs.rmSync(p, { recursive: true, force: true }); });

type Member = { dir: string; specId?: string; depends?: string[]; metadataId?: string };

function project(members: Member[]) {
  const root = fs.mkdtempSync(join(tmpdir(), "readiness-spec-id-")); roots.push(root);
  const missions = join(root, "missions"), mission = join(missions, MISSION);
  const write = (p: string, text: string) => { fs.mkdirSync(join(p, ".."), { recursive: true }); fs.writeFileSync(p, text); };
  write(join(root, "project.yaml"), YAML.stringify({ kind: "project", metadata: { id: "probe" }, proofPolicy: { judges: ["judge@probe"] }, missions: { root: "missions" } }));
  write(join(mission, "mission.yaml"), YAML.stringify({
    schema: "openrig.mission/v0alpha1", kind: "mission", metadata: { status: "active" },
    composition: { mission_markdown: { spec: "SPEC.md" }, slices: members.map((m, i) => ({ ref: `slices/${m.dir}/slice.yaml`, order: (i + 1) * 10, active: true })) },
  }));
  for (const m of members) {
    const dir = join(mission, "slices", m.dir);
    let manifest = GENERATED_SLICE;
    if (m.metadataId) manifest += `metadata:\n  id: ${m.metadataId}\n`;
    if (m.depends) manifest += `execution:\n  depends_on: ${JSON.stringify(m.depends)}\n`;
    write(join(dir, "slice.yaml"), manifest);
    const id = m.specId ? `id: ${m.specId}\n` : "";
    write(join(dir, "SPEC.md"), `---\n${id}slice: ${m.dir}\nmission: ${MISSION}\nstatus: placeholder\n---\n\n# ${m.dir}\n\n## Proof contract\n\n- [ ] Prove ${m.dir}.\n`);
    write(join(dir, "proof", "evidence.md"), `Observed outcome for ${m.dir}.\n`);
  }
  const accept = (sliceDir: string) => {
    const scope = `${MISSION}/slices/${sliceDir}`, item = readSliceReadiness(join(missions, scope)).items[0]!;
    recordJudgment(missions, { scope, item: item.id, verdict: "accept", reason: "Independent accept judgment", evidence: ["proof/evidence.md"],
      expectedRevision: item.revision, expectedPrevious: item.judgment?.id ?? null }, "judge@probe", "transport:v1");
  };
  const readiness = () => readMissionReadiness(mission);
  const eligible = (dir: string) => readiness().slices.find(s => s.scope === dir)!.eligible;
  return { root, missions, mission, accept, readiness, eligible };
}

const upstream: Member = { dir: "01-upstream", specId: "OPR.99.0.1.1" };
const downstreamOn = (name: string): Member => ({ dir: "02-downstream", specId: "OPR.99.0.1.2", depends: [name] });

describe("#1280 mission readiness resolves a dependency by the slice's generated SPEC ID", () => {
  it("a manifest edge naming the upstream's SPEC ID follows the upstream's proof", () => {
    const p = project([upstream, downstreamOn("OPR.99.0.1.1")]);
    expect(p.readiness().issues).toEqual([]);
    expect(p.eligible("02-downstream")).toBe(false); // upstream pending
    p.accept("01-upstream");
    expect(p.readiness().issues).toEqual([]);
    expect(p.eligible("01-upstream")).toBe(true);
    expect(p.eligible("02-downstream")).toBe(true);
  });

  it("the execution view's Q2 answers next_up from that resolved eligibility instead of INDETERMINATE", async () => {
    const p = project([upstream, downstreamOn("OPR.99.0.1.1")]);
    p.accept("01-upstream");
    const db = createDb(); migrate(db, ALL_MIGRATIONS);
    try {
      const view = await buildExecutionView({ db, slicesRoot: () => p.missions, buildInfo: { semver: null, commit: null, dirty: null, builtAt: null } }, { mission: MISSION });
      const q2 = view["q2_sequencing"] as Array<{ dir: string; next_up: unknown; next_up_basis: string }>;
      const downstream = q2.find(s => s.dir === "02-downstream")!;
      expect(downstream.next_up).toBe(true);
      expect(downstream.next_up_basis).toContain("dependency eligibility true");
    } finally { db.close(); }
  });

  it("the folder and metadata.id forms resolve exactly as before", () => {
    const byFolder = project([upstream, downstreamOn("01-upstream")]);
    byFolder.accept("01-upstream");
    expect(byFolder.readiness().issues).toEqual([]);
    expect(byFolder.eligible("02-downstream")).toBe(true);

    const byMetadata = project([{ ...upstream, metadataId: "explicit-upstream-key" }, downstreamOn("explicit-upstream-key")]);
    expect(byMetadata.readiness().issues).toEqual([]);
    expect(byMetadata.eligible("02-downstream")).toBe(false);
    byMetadata.accept("01-upstream");
    expect(byMetadata.eligible("02-downstream")).toBe(true);
  });

  it("an exact existing identity wins over another member whose SPEC declares the same name", () => {
    // 03-other's SPEC claims the name `01-upstream`; the edge still means the folder it always meant.
    const p = project([upstream, downstreamOn("01-upstream"), { dir: "03-other", specId: "01-upstream" }]);
    p.accept("01-upstream");
    expect(p.readiness().issues).toEqual([]);
    expect(p.eligible("02-downstream")).toBe(true); // 03-other is pending: had it been chosen, this would be false
  });

  it("a SPEC ID that two active members declare stays an unknown dependency, as before", () => {
    const p = project([upstream, downstreamOn("OPR.99.0.1.1"), { dir: "03-copy", specId: "OPR.99.0.1.1" }]);
    const r = p.readiness();
    expect(r.state).toBe("unknown");
    expect(r.issues).toEqual(["02-downstream: unknown dependency OPR.99.0.1.1"]);
    expect(r.slices.map(s => s.eligible)).toEqual([null, null, null]);
  });

  it("a name no member carries stays unknown, and a cycle through SPEC IDs is reported as a cycle", () => {
    const unknown = project([upstream, downstreamOn("OPR.99.0.1.9")]).readiness();
    expect(unknown.issues).toEqual(["02-downstream: unknown dependency OPR.99.0.1.9"]);
    expect(unknown.slices.map(s => s.eligible)).toEqual([null, null]);

    const cycle = project([{ ...upstream, depends: ["OPR.99.0.1.2"] }, downstreamOn("OPR.99.0.1.1")]).readiness();
    expect(cycle.state).toBe("unknown");
    expect(cycle.issues.join()).toContain("Cycle");
  });

  it("a SPEC frontmatter depends_on alone stays advisory: no readiness edge", () => {
    const p = project([upstream, { dir: "02-downstream", specId: "OPR.99.0.1.2" }]);
    fs.writeFileSync(join(p.mission, "slices", "02-downstream", "SPEC.md"),
      `---\nid: OPR.99.0.1.2\nslice: 02-downstream\nmission: ${MISSION}\ndepends_on: ["OPR.99.0.1.1"]\n---\n\n## Proof contract\n\n- [ ] Prove 02-downstream.\n`);
    expect(p.readiness().issues).toEqual([]);
    expect(p.eligible("02-downstream")).toBe(true); // upstream pending, yet no edge binds them
  });
});
